const {test}=require('node:test');const assert=require('node:assert/strict');
test('facets carry deterministic generator requests and do not mutate settings',async()=>{const {facetRequests}=await import('../sandbox2-runtime/workbench-model.mjs');const settings={vegetation:2};const a=facetRequests('home',{home:1,yard:2},42,settings);assert.equal(a.length,3);assert.deepEqual(a.map(r=>r.chosen),['home','yard','home']);assert.equal(new Set(a.map(r=>r.variation)).size,3);assert.deepEqual(a,facetRequests('home',{home:1,yard:2},42,settings));a[0].settings.vegetation=0;assert.equal(settings.vegetation,2);assert.equal(a[1].settings.vegetation,2);});
test('only Town requests supported simulation growth stages',async()=>{const {facetRequests}=await import('../sandbox2-runtime/workbench-model.mjs');assert.deepEqual(facetRequests('town',{town:1},1).map(r=>r.settings.growthStage),[0,1,3]);assert.ok(facetRequests('woodland',{wood:1},1).every(r=>r.settings.growthStage===undefined));});

test("growth is seeded, connected, nested and changes silhouette",async()=>{const {grownCells}=await import("../sandbox2-runtime/workbench-model.mjs");const cells=[{q:0,r:0},{q:1,r:0},{q:0,r:1},{q:-1,r:1},{q:-1,r:0},{q:0,r:-1},{q:1,r:-1}];const shapes=new Set();for(let seed=1;seed<30;seed++){const a=grownCells(cells,3,seed);assert.equal(new Set(a).size,3);assert.deepEqual(a.slice(0,2),grownCells(cells,2,seed));shapes.add(a.join(","));for(let i=1;i<a.length;i++)assert.ok(a.slice(0,i).some(j=>{const u=cells[j],v=cells[a[i]];return Math.max(Math.abs(u.q-v.q),Math.abs(u.r-v.r),Math.abs(u.q+u.r-v.q-v.r))===1;}));}assert.ok(shapes.size>3);});
test('loaded scenes retain independent settings, seeds and rotation across switches',async()=>{const {createLoadoutStore}=await import('../sandbox2-runtime/workbench-model.mjs');const store=createLoadoutStore(),ranch={chosen:'pasture',variation:123,rotation:3,settings:{vegetation:0,props:0,generatedGrowth:true}};store.remember('ranch',ranch);store.remember('home',{chosen:'lane',variation:456,rotation:0,settings:{vegetation:3,props:1}});ranch.settings.vegetation=2;const loaded=store.get('ranch');assert.equal(loaded.settings.vegetation,0);assert.equal(loaded.rotation,3);assert.equal(loaded.variation,123);loaded.settings.props=1;assert.equal(store.get('ranch').settings.props,0);assert.equal(store.get('home').settings.vegetation,3);assert.equal(store.get('unknown'),null);});
